# Headless mirror refresh schema

Secret-free local orchestration configuration. Private keys, API tokens, passwords, and wallet credentials are prohibited.

```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://forkmesh.com/schemas/headless-mirror-refresh-v1.json",
  "title": "ForkMesh headless mirror refresh configuration",
  "description": "Secret-free local orchestration configuration. Private keys, API tokens, passwords, and wallet credentials are prohibited.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "type",
    "sourceRepository",
    "archiveDirectory",
    "gatewayConfigPath",
    "identityStateDirectory",
    "identityHelperPath",
    "mirrorGatewayPath",
    "pythonProgram",
    "gitProgram",
    "manifestPath",
    "nodeOwner",
    "repositoryName",
    "ownerAliases",
    "workerOrigin",
    "publicOrigin",
    "listen",
    "operations"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "type": {
      "const": "forkmesh.headless-mirror-refresh"
    },
    "sourceRepository": {
      "$ref": "#/$defs/absolutePath"
    },
    "archiveDirectory": {
      "description": "Owner-controlled legacy cleanup directory. New public refreshes create no archives; existing archive-*.age generations are removed after plaintext activation.",
      "$ref": "#/$defs/absolutePath"
    },
    "releaseStore": {
      "description": "Optional owner-local content-addressed store for explicitly published immutable release assets.",
      "$ref": "#/$defs/absolutePath"
    },
    "gatewayConfigPath": {
      "$ref": "#/$defs/absolutePath"
    },
    "identityStateDirectory": {
      "$ref": "#/$defs/absolutePath"
    },
    "identityHelperPath": {
      "$ref": "#/$defs/absolutePath"
    },
    "mirrorGatewayPath": {
      "$ref": "#/$defs/absolutePath"
    },
    "pythonProgram": {
      "$ref": "#/$defs/absolutePath"
    },
    "gitProgram": {
      "$ref": "#/$defs/absolutePath"
    },
    "manifestPath": {
      "$ref": "#/$defs/absolutePath"
    },
    "nodeOwner": {
      "$ref": "#/$defs/nodeName"
    },
    "repositoryName": {
      "type": "string",
      "minLength": 1,
      "maxLength": 100,
      "pattern": "^[A-Za-z0-9._-]+$"
    },
    "ownerAliases": {
      "description": "Unique public owner paths served from the same plaintext bare repository. The configured nodeOwner must be present.",
      "type": "array",
      "minItems": 1,
      "maxItems": 16,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/nodeName"
      }
    },
    "workerOrigin": {
      "$ref": "#/$defs/httpsOrigin"
    },
    "publicOrigin": {
      "$ref": "#/$defs/httpsOrigin"
    },
    "mirrorUrl": {
      "description": "Optional independently reachable public HTTPS Git origin. Omit to retain Tunnel-proxied Git fallback.",
      "$ref": "#/$defs/httpsOrigin"
    },
    "listen": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "host",
        "port"
      ],
      "properties": {
        "host": {
          "enum": [
            "127.0.0.1",
            "::1",
            "localhost"
          ]
        },
        "port": {
          "type": "integer",
          "minimum": 1,
          "maximum": 65535
        }
      }
    },
    "operations": {
      "description": "The runtime additionally requires git-info-refs, git-upload-pack, tree, blob, and raw.",
      "type": "array",
      "minItems": 5,
      "maxItems": 19,
      "uniqueItems": true,
      "items": {
        "enum": [
          "git-info-refs",
          "git-upload-pack",
          "tree",
          "blobs",
          "blob",
          "raw",
          "history",
          "commit",
          "compare",
          "branches",
          "search",
          "stats",
          "sizes",
          "release-blob",
          "merge-pull",
          "merge-preview",
          "update-pull-branch",
          "actions-status",
          "actions-control"
        ]
      },
      "allOf": [
        {
          "contains": {
            "const": "git-info-refs"
          }
        },
        {
          "contains": {
            "const": "git-upload-pack"
          }
        },
        {
          "contains": {
            "const": "tree"
          }
        },
        {
          "contains": {
            "const": "blob"
          }
        },
        {
          "contains": {
            "const": "raw"
          }
        },
        {
          "if": {
            "contains": {
              "const": "actions-control"
            }
          },
          "then": {
            "contains": {
              "const": "actions-status"
            }
          }
        }
      ]
    },
    "writableRepositoryRoot": {
      "description": "Optional owner-controlled mode-0700 directory under which an authorized first push creates <owner>/<name>.git. Rendered verbatim into the gateway configuration; its presence is what allows any repository to be rendered with git-receive-pack. Omit to keep the node read-only.",
      "$ref": "#/$defs/absolutePath"
    },
    "writableOwners": {
      "description": "Owners whose push-created repositories the refresh cycle renders from the gateway's hosted-pushes.json sidecar. Requires writableRepositoryRoot. An empty or omitted list renders no push-created repository and no git-receive-pack operation.",
      "type": "array",
      "maxItems": 64,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/writableOwner"
      }
    },
    "receiveMaxInputBytes": {
      "description": "Optional receive.maxInputSize rendered as limits.receiveMaxInputBytes in the gateway configuration. Requires writableRepositoryRoot.",
      "type": "integer",
      "minimum": 1048576,
      "maximum": 4294967296
    },
    "catalog": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "description": {
          "type": "string",
          "maxLength": 240
        },
        "solana": {
          "description": "Optional public self-custodial payout address; never a private key.",
          "type": "string",
          "pattern": "^(?:|[1-9A-HJ-NP-Za-km-z]{32,44})$"
        },
        "channel": {
          "type": "string",
          "maxLength": 120
        },
        "hostedSince": {
          "type": "string",
          "pattern": "^(?:|[1-9][0-9]{0,18})$"
        },
        "branch": {
          "type": "string",
          "maxLength": 120
        },
        "platform": {
          "type": "string",
          "maxLength": 16
        },
        "version": {
          "type": "string",
          "maxLength": 32
        },
        "actionsEnabled": {
          "description": "Owner-approved upper bound for this node's public Actions capability. Defaults to false; live enabled/running state additionally requires a fresh protected actions-state.json lease (same-account mode 0600 or the fixed root:gateway-group mode-0640 handoff).",
          "type": "boolean",
          "default": false
        },
        "reportCpu": {
          "description": "Opt in to publishing a bounded aggregate host CPU percentage. Defaults to false.",
          "type": "boolean",
          "default": false
        },
        "reportMemory": {
          "description": "Opt in to publishing bounded host memory used/total bytes. Defaults to false.",
          "type": "boolean",
          "default": false
        },
        "reportDisk": {
          "description": "Opt in to publishing bounded used/total bytes for the filesystem containing sourceRepository. Defaults to false.",
          "type": "boolean",
          "default": false
        }
      }
    }
  },
  "$defs": {
    "absolutePath": {
      "type": "string",
      "minLength": 2,
      "maxLength": 4096,
      "pattern": "^/"
    },
    "nodeName": {
      "type": "string",
      "pattern": "^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$"
    },
    "writableOwner": {
      "description": "An owner name, or the single entry \"*\" accepting every owner the control plane authorized (a node holding website-created repositories). The wildcard may not be mixed with named owners.",
      "type": "string",
      "pattern": "^(?:\\*|[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?)$"
    },
    "httpsOrigin": {
      "type": "string",
      "maxLength": 261,
      "pattern": "^https://[A-Za-z0-9.-]+/?$"
    }
  }
}
```

# Mirror actions catalog configuration schema

Secret-free bounded stdin request used only to toggle the owner-approved public Actions capability and renew its signed catalog record.

```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://forkmesh.com/schemas/mirror-actions-catalog-configuration-v1.json",
  "title": "ForkMesh mirror Actions catalog configuration request",
  "description": "Secret-free bounded stdin request used only to toggle the owner-approved public Actions capability and renew its signed catalog record.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "type",
    "actionsEnabled"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "type": {
      "const": "forkmesh.mirror-actions-catalog-configuration"
    },
    "actionsEnabled": {
      "type": "boolean"
    }
  }
}
```

# Mirror actions control schema

One pending control request, written atomically (mode 0640) by the mirror gateway as {actionsControlPath}/{body requestId}.json and consumed by the Actions executor. The gateway…

```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://forkmesh.com/schemas/mirror-actions-control-v1.json",
  "title": "ForkMesh mirror Actions control envelope",
  "description": "One pending control request, written atomically (mode 0640) by the mirror gateway as {actionsControlPath}/{body requestId}.json and consumed by the Actions executor. The gateway is a courier: the executor recomputes sha256(body), rebuilds the canonical capability message and verifies the router's Ed25519 signature before it parses or applies body. Runtime policy bounds the file to 16 KiB and body to 4 KiB. See operations/mirror-actions-control.md.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "type",
    "node",
    "owner",
    "repository",
    "receivedAt",
    "capability",
    "body"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "type": {
      "const": "forkmesh.mirror-actions-control"
    },
    "node": {
      "type": "string",
      "pattern": "^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$"
    },
    "owner": {
      "type": "string",
      "pattern": "^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$"
    },
    "repository": {
      "type": "string",
      "pattern": "^[A-Za-z0-9._-]{1,100}$"
    },
    "receivedAt": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991
    },
    "capability": {
      "$ref": "#/$defs/capability"
    },
    "body": {
      "description": "The exact request body bytes as a UTF-8 string; it parses to #/$defs/request. Never re-serialized: bodySha256 covers these bytes.",
      "type": "string",
      "minLength": 2,
      "maxLength": 4096,
      "contentMediaType": "application/json",
      "contentSchema": {
        "$ref": "#/$defs/request"
      }
    }
  },
  "$defs": {
    "capability": {
      "description": "The router capability headers the gateway verified for this request.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "method",
        "path",
        "requestId",
        "issuedAt",
        "bodySha256",
        "signature"
      ],
      "properties": {
        "method": {
          "const": "POST"
        },
        "path": {
          "type": "string",
          "pattern": "^/v1/repositories/[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?/[A-Za-z0-9._-]{1,100}/actions-control$"
        },
        "requestId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]{12,80}$"
        },
        "issuedAt": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "bodySha256": {
          "type": "string",
          "pattern": "^[0-9a-f]{64}$"
        },
        "signature": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]{86}$"
        }
      }
    },
    "workflowPath": {
      "type": "string",
      "pattern": "^\\.forkmesh/[A-Za-z0-9._-]{1,96}\\.ya?ml$"
    },
    "runId": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991
    },
    "request": {
      "description": "Worker-to-gateway request body (forkmesh.actions-control-v1). Exactly the common keys plus the keys of its action.",
      "type": "object",
      "required": [
        "schemaVersion",
        "type",
        "requestId",
        "action",
        "actor",
        "issuedAt"
      ],
      "properties": {
        "schemaVersion": {
          "const": 1
        },
        "type": {
          "const": "forkmesh.actions-control-v1"
        },
        "requestId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]{16,64}$"
        },
        "action": {
          "enum": [
            "dispatch",
            "rerun",
            "cancel",
            "approve",
            "reject",
            "set-workflow-enabled",
            "set-repository-enabled"
          ]
        },
        "actor": {
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9._-]{0,63}$"
        },
        "issuedAt": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "workflow": {
          "$ref": "#/$defs/workflowPath"
        },
        "ref": {
          "type": "string",
          "pattern": "^refs/heads/(?!.*(?:\\.\\.|//))[A-Za-z0-9._/-]{1,200}(?<!/)(?<!\\.lock)$"
        },
        "runId": {
          "$ref": "#/$defs/runId"
        },
        "enabled": {
          "type": "boolean"
        }
      },
      "unevaluatedProperties": false,
      "oneOf": [
        {
          "properties": {
            "action": {
              "const": "dispatch"
            },
            "runId": false,
            "enabled": false
          },
          "required": [
            "workflow",
            "ref"
          ]
        },
        {
          "properties": {
            "action": {
              "enum": [
                "rerun",
                "cancel",
                "approve",
                "reject"
              ]
            },
            "workflow": false,
            "ref": false,
            "enabled": false
          },
          "required": [
            "runId"
          ]
        },
        {
          "properties": {
            "action": {
              "const": "set-workflow-enabled"
            },
            "ref": false,
            "runId": false
          },
          "required": [
            "workflow",
            "enabled"
          ]
        },
        {
          "properties": {
            "action": {
              "const": "set-repository-enabled"
            },
            "workflow": false,
            "ref": false,
            "runId": false
          },
          "required": [
            "enabled"
          ]
        }
      ]
    }
  }
}
```

# Mirror actions state schema

Short-lived, owner-local executor state read by the headless mirror catalog publisher. This document is never a workflow, command, variable, log, or source of authorization.

```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://forkmesh.com/schemas/mirror-actions-state-v1.json",
  "title": "ForkMesh mirror Actions runtime lease",
  "description": "Short-lived, owner-local executor state read by the headless mirror catalog publisher. This document is never a workflow, command, variable, log, or source of authorization.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "type",
    "node",
    "state",
    "updatedAt",
    "expiresAt"
  ],
  "properties": {
    "schemaVersion": {
      "const": 1
    },
    "type": {
      "const": "forkmesh.mirror-actions-state"
    },
    "node": {
      "type": "string",
      "pattern": "^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$"
    },
    "state": {
      "enum": [
        "disabled",
        "enabled",
        "running"
      ]
    },
    "updatedAt": {
      "description": "UTC Unix time in milliseconds. Runtime policy requires it to be fresh and within the bounded lease horizon.",
      "type": "integer",
      "minimum": 0,
      "maximum": 9007199254740991
    },
    "expiresAt": {
      "description": "UTC Unix time in milliseconds. Runtime policy requires it to be in the future and no more than 15 minutes ahead.",
      "type": "integer",
      "minimum": 0,
      "maximum": 9007199254740991
    }
  }
}
```

# Mirror actions summary schema

Short-lived, secret-free run metadata written atomically by the node owner. Runtime policy additionally requires a positive lease no longer than 15 minutes and a UTF-8 logTail no…

```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://forkmesh.com/schemas/mirror-actions-summary-v1.json",
  "title": "ForkMesh mirror Actions public summary",
  "description": "Short-lived, secret-free run metadata written atomically by the node owner. Runtime policy additionally requires a positive lease no longer than 15 minutes and a UTF-8 logTail no larger than 16 KiB. Version 1 is the original document. Version 2 adds per-run workflowPath, pullNumber and steps plus the top-level repositories catalog and controls outcomes (see operations/mirror-actions-control.md); neither version carries workflow content, commands, variables, or local paths.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "type",
    "node",
    "updatedAt",
    "expiresAt",
    "runs"
  ],
  "properties": {
    "schemaVersion": {
      "enum": [
        1,
        2
      ]
    },
    "type": {
      "const": "forkmesh.mirror-actions-summary"
    },
    "node": {
      "type": "string",
      "pattern": "^[a-z](?:[a-z0-9-]{0,61}[a-z0-9])?$"
    },
    "updatedAt": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991
    },
    "expiresAt": {
      "type": "integer",
      "minimum": 1,
      "maximum": 9007199254740991
    },
    "runs": {
      "type": "array",
      "maxItems": 20,
      "items": {
        "$ref": "#/$defs/run"
      }
    },
    "repositories": {
      "type": "array",
      "maxItems": 64,
      "items": {
        "$ref": "#/$defs/repository"
      }
    },
    "controls": {
      "description": "Newest first. A request id may repeat when a replayed envelope is rejected after the original was applied.",
      "type": "array",
      "maxItems": 32,
      "items": {
        "$ref": "#/$defs/control"
      }
    }
  },
  "oneOf": [
    {
      "title": "Version 1",
      "properties": {
        "schemaVersion": {
          "const": 1
        },
        "repositories": false,
        "controls": false,
        "runs": {
          "items": {
            "properties": {
              "workflowPath": false,
              "pullNumber": false,
              "steps": false
            }
          }
        }
      }
    },
    {
      "title": "Version 2",
      "required": [
        "repositories",
        "controls"
      ],
      "properties": {
        "schemaVersion": {
          "const": 2
        },
        "runs": {
          "items": {
            "required": [
              "id",
              "owner",
              "repository",
              "workflow",
              "commit",
              "ref",
              "status",
              "createdAt",
              "startedAt",
              "finishedAt",
              "logTail",
              "workflowPath",
              "pullNumber",
              "steps"
            ]
          }
        }
      }
    }
  ],
  "$defs": {
    "timestampOrZero": {
      "type": "integer",
      "minimum": 0,
      "maximum": 9007199254740991
    },
    "run": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "owner",
        "repository",
        "workflow",
        "commit",
        "ref",
        "status",
        "createdAt",
        "startedAt",
        "finishedAt",
        "logTail"
      ],
      "properties": {
        "id": {
          "type": "integer",
          "minimum": 1,
          "maximum": 2147483647
        },
        "owner": {
          "type": "string",
          "pattern": "^[A-Za-z0-9._-]{1,100}$"
        },
        "repository": {
          "type": "string",
          "pattern": "^[A-Za-z0-9._-]{1,100}$"
        },
        "workflow": {
          "type": "string",
          "minLength": 1,
          "maxLength": 160
        },
        "commit": {
          "type": "string",
          "pattern": "^(?:[0-9a-f]{40}|[0-9a-f]{64})$"
        },
        "ref": {
          "type": "string",
          "pattern": "^refs/(?:heads|tags)/(?!/)(?!.*(?:\\.\\.|//))[A-Za-z0-9._/-]{1,160}(?<!/)$"
        },
        "status": {
          "enum": [
            "awaiting-approval",
            "queued",
            "running",
            "success",
            "failed",
            "rejected",
            "cancelled",
            "skipped"
          ]
        },
        "createdAt": {
          "type": "integer",
          "minimum": 1,
          "maximum": 9007199254740991
        },
        "startedAt": {
          "$ref": "#/$defs/timestampOrZero"
        },
        "finishedAt": {
          "$ref": "#/$defs/timestampOrZero"
        },
        "logTail": {
          "description": "Tail of ActionStore's already-redacted UTF-8 log. Runtime enforces a 16 KiB encoded-byte limit.",
          "type": "string",
          "maxLength": 16384
        },
        "workflowPath": {
          "description": "Version 2 only. Empty when the run has no workflow file.",
          "type": "string",
          "pattern": "^(?:|\\.forkmesh/[A-Za-z0-9._-]{1,96}\\.ya?ml)$"
        },
        "pullNumber": {
          "description": "Version 2 only. 0 when the run is not a pull-request run.",
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "steps": {
          "description": "Version 2 only.",
          "type": "array",
          "maxItems": 64,
          "items": {
            "$ref": "#/$defs/step"
          }
        }
      }
    },
    "step": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "status"
      ],
      "properties": {
        "name": {
          "type": "string",
          "maxLength": 120,
          "pattern": "^[^\\u0000\\r\\n]*$"
        },
        "status": {
          "enum": [
            "pending",
            "running",
            "success",
            "failed",
            "skipped",
            "cancelled"
          ]
        }
      }
    },
    "repository": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "owner",
        "repository",
        "actionsEnabled",
        "workflows"
      ],
      "properties": {
        "owner": {
          "type": "string",
          "pattern": "^[A-Za-z0-9._-]{1,100}$"
        },
        "repository": {
          "type": "string",
          "pattern": "^[A-Za-z0-9._-]{1,100}$"
        },
        "actionsEnabled": {
          "type": "boolean"
        },
        "workflows": {
          "type": "array",
          "maxItems": 32,
          "items": {
            "$ref": "#/$defs/workflow"
          }
        }
      }
    },
    "workflow": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path",
        "name",
        "events",
        "manual",
        "enabled",
        "runsOn",
        "valid"
      ],
      "properties": {
        "path": {
          "type": "string",
          "pattern": "^\\.forkmesh/[A-Za-z0-9._-]{1,96}\\.ya?ml$"
        },
        "name": {
          "type": "string",
          "maxLength": 160,
          "pattern": "^[^\\u0000\\r\\n]*$"
        },
        "events": {
          "type": "array",
          "maxItems": 8,
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 40,
            "pattern": "^[^\\u0000\\r\\n]*$"
          }
        },
        "manual": {
          "type": "boolean"
        },
        "enabled": {
          "type": "boolean"
        },
        "runsOn": {
          "type": "array",
          "maxItems": 8,
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 64,
            "pattern": "^[^\\u0000\\r\\n]*$"
          }
        },
        "valid": {
          "type": "boolean"
        }
      }
    },
    "control": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "owner",
        "repository",
        "requestId",
        "action",
        "status",
        "reason",
        "runId",
        "finishedAt"
      ],
      "properties": {
        "owner": {
          "type": "string",
          "pattern": "^[A-Za-z0-9._-]{1,100}$"
        },
        "repository": {
          "type": "string",
          "pattern": "^[A-Za-z0-9._-]{1,100}$"
        },
        "requestId": {
          "type": "string",
          "pattern": "^[A-Za-z0-9_-]{16,64}$"
        },
        "action": {
          "enum": [
            "dispatch",
            "rerun",
            "cancel",
            "approve",
            "reject",
            "set-workflow-enabled",
            "set-repository-enabled"
          ]
        },
        "status": {
          "enum": [
            "applied",
            "rejected"
          ]
        },
        "reason": {
          "enum": [
            "",
            "actions_disabled",
            "invalid_request",
            "not_awaiting_approval",
            "not_cancellable",
            "not_manual",
            "operator_disabled",
            "ref_not_found",
            "repository_not_found",
            "run_not_found",
            "workflow_disabled",
            "workflow_invalid",
            "workflow_not_found",
            "wrong_node"
          ]
        },
        "runId": {
          "type": "integer",
          "minimum": 0,
          "maximum": 9007199254740991
        },
        "finishedAt": {
          "$ref": "#/$defs/timestampOrZero"
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "status": {
                "const": "applied"
              }
            }
          },
          "then": {
            "properties": {
              "reason": {
                "const": ""
              }
            }
          },
          "else": {
            "properties": {
              "reason": {
                "minLength": 1
              }
            }
          }
        }
      ]
    }
  }
}
